using EduConnect.Mvc.Models;
using EduConnect.Mvc.Infrastructure;
using EduConnect.Mvc.Areas.NhuCau.ViewModels;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using System.Net;
using Xunit;
internal static partial class Cases
{
 internal static async Task NeedCases(Fixture f,string key)
 {
  if(key=="need_store"||key=="need_rollback"||key=="need_cancel"){
   var n=f.NeedInput();if(key=="need_rollback")n.MonHocIds=[f.M1,int.MaxValue];
   await using var s=f.Scope(f.H);
   if(key=="need_cancel"){
    await using var blocker=new SqlConnection(Fixture.Connection);await blocker.OpenAsync();await using var tx=blocker.BeginTransaction();await using var cmd=blocker.CreateCommand();cmd.Transaction=tx;cmd.CommandText="SELECT Id FROM dbo.AspNetUsers WITH (UPDLOCK,HOLDLOCK) WHERE Id=@u";cmd.Parameters.AddWithValue("@u",f.H);await cmd.ExecuteScalarAsync();using var ct=new CancellationTokenSource(TimeSpan.FromSeconds(2));
    try{var exception=await Capture(async()=>{var r=await s.Needs.TaoNhuCauHocAsync(n,f.H,ct.Token);Assert.False(r.ThanhCong,"Không được trả thành công sau hủy");});Assert.True(ct.IsCancellationRequested);Assert.True(exception is OperationCanceledException || exception is SqlException sql && sql.Number==0 && sql.Message.Contains("cancel",StringComparison.OrdinalIgnoreCase),exception?.ToString()??"Call không ném kết quả hủy");}finally{await tx.RollbackAsync();}
   }else{var r=await s.Needs.TaoNhuCauHocAsync(n,f.H,default);f.Proof["return"]=new{r.ThanhCong,r.MaTrangThai,r.ThongBao};if(key=="need_store"){Assert.True(r.ThanhCong,r.ThongBao);f.Need=r.DuLieu;Assert.NotEqual(Guid.Empty,f.Need);}else{Assert.False(r.ThanhCong);Assert.Contains("Môn",r.ThongBao!,StringComparison.OrdinalIgnoreCase);}}
   await using var db=f.Db();var ns=await db.Set<NhuCauHoc>().Where(x=>x.ChuSoHuuId==f.H).ToListAsync();f.Proof["needs"]=ns;
   if(key=="need_store"){Assert.Single(ns);Assert.Equal(2,await db.Set<NhuCauMonHoc>().CountAsync(x=>x.NhuCauId==f.Need));Assert.Equal(2,await db.Set<KhungGioRanh>().CountAsync(x=>x.NhuCauId==f.Need));Assert.Single(await db.Set<LuotDangNhuCau>().Where(x=>x.TaiKhoanId==f.H).ToListAsync());}else{Assert.Empty(ns);Assert.False(await db.Set<LuotDangNhuCau>().AnyAsync(x=>x.TaiKhoanId==f.H));}return;
  }
  switch(key){
  case "need_create_http":case "need_draft":case "need_parent":{
   var actor=key=="need_parent"?f.P:f.H;using var c=await f.Client(actor);var n=f.NeedInput();if(key=="need_draft"){n.BanNhap=true;n.MucTieu=null;n.LichRanh=[];}var form=f.NeedForm(n);if(key=="need_parent"){form["TenNguoiHoc"]="An";form["TuoiNguoiHoc"]="14";}
   using var r=await f.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",form,"/NhuCau/NhuCau/Tao");Assert.Equal(HttpStatusCode.OK,r.StatusCode);var body=await r.Content.ReadAsStringAsync();Assert.Contains("\"ok\":true",body);await using var db=f.Db();var row=await db.Set<NhuCauHoc>().SingleAsync(x=>x.ChuSoHuuId==actor);Assert.Equal(n.MucTieu,row.MucTieu);Assert.Equal(actor,row.ChuSoHuuId);Assert.Equal(2,await db.Set<NhuCauMonHoc>().CountAsync(x=>x.NhuCauId==row.Id));Assert.Equal(n.LichRanh.Count,await db.Set<KhungGioRanh>().CountAsync(x=>x.NhuCauId==row.Id));Assert.Equal(n.BanNhap?0:1,await db.Set<LuotDangNhuCau>().CountAsync(x=>x.TaiKhoanId==actor));if(key=="need_parent"){Assert.Equal("An",row.TenNguoiHoc);Assert.Equal(14,row.TuoiNguoiHoc);}if(n.BanNhap)Assert.Equal("BanNhap",row.TrangThai);break;}
  case "need_auth":{
   using var guest=await f.Client();using var denied=await f.Post(guest,"/NhuCau/NhuCau/TaoNhuCauHoc",f.NeedForm());Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);using var tutor=await f.Client(f.G);using var r=await f.Post(tutor,"/NhuCau/NhuCau/TaoNhuCauHoc",f.NeedForm());Assert.Equal((HttpStatusCode)422,r.StatusCode);await using var db=f.Db();Assert.False(await db.Set<NhuCauHoc>().AnyAsync(x=>x.ChuSoHuuId==f.G||x.ChuSoHuuId==f.H));break;}
  case "need_csrf":{
   IntegrationLogCapture.Clear();using var c=await f.Client(f.H);using var r=await f.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",f.NeedForm(),csrf:false);Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);await using var db=f.Db();Assert.False(await db.Set<NhuCauHoc>().AnyAsync(x=>x.ChuSoHuuId==f.H));Assert.True(await db.Set<NhatKyAnToan>().AsNoTracking().AnyAsync(x=>x.TaiKhoanId==f.H&&x.SuKien=="NhuCau.TaoNhuCauHoc"&&x.KetQua=="TuChoi"&&x.LyDo=="CSRFKhongHopLe"),"Request thiếu CSRF phải được audit là Authorization/TuChoi với lý do CSRFKhongHopLe.");break;}
  case "need_update":{
   using var c=await f.Client(f.H);var n=f.NeedInput();await using(var s=f.Scope(f.H)){var k=await s.Needs.TaoNhuCauHocAsync(n,f.H,default);Assert.True(k.ThanhCong,k.ThongBao);f.Need=k.DuLieu;}await using var db=f.Db();var old=await db.Set<NhuCauHoc>().AsNoTracking().SingleAsync(x=>x.Id==f.Need);var form=f.NeedForm();form["MaNhuCau"]=f.Need.ToString();form["RowVersion"]=Convert.ToBase64String(old.RowVersion);form["MonHocIds[0]"]=f.M2.ToString();form.Remove("MonHocIds[1]");form["MucTieu"]="Cập nhật";form["LichRanh[0].GioBatDau"]="18:00";using var r=await f.Post(c,"/NhuCau/NhuCau/CapNhat?maNhuCau="+f.Need,form,"/NhuCau/NhuCau/Sua/"+f.Need);Assert.Equal(HttpStatusCode.OK,r.StatusCode);await using var fresh=f.Db();var row=await fresh.Set<NhuCauHoc>().SingleAsync(x=>x.Id==f.Need);Assert.Equal(old.TaoLuc,row.TaoLuc);Assert.Equal(f.H,row.ChuSoHuuId);Assert.NotEqual(Convert.ToBase64String(old.RowVersion),Convert.ToBase64String(row.RowVersion));Assert.Single(await fresh.Set<NhuCauMonHoc>().Where(x=>x.NhuCauId==f.Need&&x.MonHocId==f.M2).ToListAsync());Assert.Equal(1,await fresh.Set<LuotDangNhuCau>().CountAsync(x=>x.TaiKhoanId==f.H));break;}
  case "need_owner_version":{
   await f.SeedNeed();var rv=await f.Version<NhuCauHoc>(f.Need);await f.Sql("UPDATE dbo.NhuCauHoc SET MucTieu=N'Phiên bản mới' WHERE Id=@n",new(){{"@n",f.Need}});foreach(var actor in new[]{f.X,f.H}){using var c=await f.Client(actor);var form=f.NeedForm();form["MaNhuCau"]=f.Need.ToString();form["RowVersion"]=Convert.ToBase64String(rv);using var r=await f.Post(c,"/NhuCau/NhuCau/CapNhat?maNhuCau="+f.Need,form);Assert.Equal((HttpStatusCode)422,r.StatusCode);}await using var db=f.Db();Assert.Equal("Phiên bản mới",(await db.Set<NhuCauHoc>().SingleAsync(x=>x.Id==f.Need)).MucTieu);break;}
  case "need_fields":{
   using var c=await f.Client(f.H);var fields=new[]{("SoBuoiTuan","abc"),("HinhThucHoc","TrucTiep"),("DonViHocPhi","")};foreach(var (field,val) in fields){f.Proof["fieldUnderTest"]=field;var form=f.NeedForm();form[field]=val;if(field=="HinhThucHoc"){form["KhuVuc"]="Thành phố Hà Nội";form["PhuongXa"]="Phường Bến Thành";form["DiaChiChiTiet"]="10 Test";}using var r=await f.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",form);Assert.Equal((HttpStatusCode)422,r.StatusCode);}await using var db=f.Db();Assert.False(await db.Set<NhuCauHoc>().AnyAsync(x=>x.ChuSoHuuId==f.H));Assert.True(await db.Set<NhatKyAnToan>().AsNoTracking().AnyAsync(x=>x.TaiKhoanId==f.H&&x.SuKien=="NhuCau.TaoNhuCauHoc"&&x.KetQua=="TuChoi"&&x.LyDo=="CSRFKhongHopLe"),"Request thiếu CSRF phải được audit là Authorization/TuChoi với lý do CSRFKhongHopLe.");break;}
  case "need_limit":{
   for(int dl=0;dl<3;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();var count=dl==1?5:3;for(int i=0;i<count;i++){await d.SeedNeed();if(dl==1)await d.Sql("UPDATE dbo.NhuCauHoc SET TrangThai='BanNhap' WHERE Id=@n",new(){{"@n",d.Need}});if(dl==2)await d.Sql("UPDATE dbo.NhuCauHoc SET TrangThai='DaDong' WHERE Id=@n; INSERT dbo.LuotDangNhuCau(Id,NhuCauId,TaiKhoanId,MaThaoTac,HanhDong,NgayDang,DangLuc) VALUES(NEWID(),@n,@u,NEWID(),'Dang',CONVERT(date,SWITCHOFFSET(SYSDATETIMEOFFSET(),'+07:00')),SYSDATETIMEOFFSET())",new(){{"@n",d.Need},{"@u",d.H}});}using var c=await d.Client(d.H);var input=d.NeedInput();input.BanNhap=dl==1;using var r=await d.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",d.NeedForm(input));Assert.Equal((HttpStatusCode)422,r.StatusCode);await using var db=d.Db();Assert.Equal(count,await db.Set<NhuCauHoc>().CountAsync(x=>x.ChuSoHuuId==d.H));}break;}
  case "need_duplicate":{
   var n=f.NeedInput();n.MucTieu="  Ôn tập toán  ";await using(var s=f.Scope(f.H)){var k=await s.Needs.TaoNhuCauHocAsync(n,f.H,default);Assert.True(k.ThanhCong,k.ThongBao);}n.MucTieu="ÔN TẬP TOÁN";n.MonHocIds.Reverse();n.LichRanh.Reverse();foreach(var actor in new[]{f.H,f.X}){using var c=await f.Client(actor);n.MaThaoTac=Guid.NewGuid();using var r=await f.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",f.NeedForm(n));Assert.Equal(actor==f.H?(HttpStatusCode)422:HttpStatusCode.OK,r.StatusCode);}await using var db=f.Db();Assert.Equal(1,await db.Set<NhuCauHoc>().CountAsync(x=>x.ChuSoHuuId==f.H));Assert.Equal(1,await db.Set<NhuCauHoc>().CountAsync(x=>x.ChuSoHuuId==f.X));break;}
  case "need_close":{
   await f.SeedNeed();using var c=await f.Client(f.H);foreach(var state in new[]{"DaDong","DangMo"}){using var r=await f.Post(c,"/NhuCau/NhuCau/TrangThai",new(){{"id",f.Need.ToString()},{"state",state},{"rowVersion",Convert.ToBase64String(await f.Version<NhuCauHoc>(f.Need))}});Assert.Equal(HttpStatusCode.OK,r.StatusCode);}using var confirm=await f.Post(c,"/NhuCau/NhuCau/XacNhanConNhuCau",new(){{"id",f.Need.ToString()},{"rowVersion",Convert.ToBase64String(await f.Version<NhuCauHoc>(f.Need))}});Assert.Equal(HttpStatusCode.OK,confirm.StatusCode);await using var db=f.Db();var n=await db.Set<NhuCauHoc>().SingleAsync(x=>x.Id==f.Need);Assert.Equal("DangMo",n.TrangThai);Assert.NotNull(n.XacNhanConNhuCauLuc);Assert.Equal(1,await db.Set<LuotDangNhuCau>().CountAsync(x=>x.NhuCauId==f.Need));break;}
  case "mvc_contract":{
   foreach(var dl in new[]{"Form","Ajax","Invalid"}){await using var d=new Fixture(f.Id+"-"+dl);await d.Init();using var c=await d.Client(d.H);var form=d.NeedForm();if(dl=="Invalid")form["MucTieu"]="";using var r=await d.Post(c,"/NhuCau/NhuCau/TaoNhuCauHoc",form,"/NhuCau/NhuCau/Tao",ajax:dl!="Form");await using var db=d.Db();if(dl=="Form"){Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);Assert.Equal("/NhuCau/NhuCau",r.Headers.Location!.OriginalString);Assert.Single(await db.Set<NhuCauHoc>().Where(x=>x.ChuSoHuuId==d.H).ToListAsync());}else if(dl=="Ajax"){Assert.Equal(HttpStatusCode.OK,r.StatusCode);var body=await r.Content.ReadAsStringAsync();Assert.Contains("\"ok\":true",body);Assert.Contains("redirectUrl",body);Assert.Single(await db.Set<NhuCauHoc>().Where(x=>x.ChuSoHuuId==d.H).ToListAsync());}else{Assert.Equal((HttpStatusCode)422,r.StatusCode);var body=await r.Content.ReadAsStringAsync();Assert.Contains("\"ok\":false",body);Assert.Contains("MucTieu",body);Assert.Empty(await db.Set<NhuCauHoc>().Where(x=>x.ChuSoHuuId==d.H).ToListAsync());}}
   break;}
  default:throw new InvalidOperationException(key);
  }
 }
}
